    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 1, 1, '{"en": "Hero Commitment", "ms-MY": "Ikrar Hero", "id-ID": "Komitmen Hero"}'::jsonb, '{"en": "Decide why you are doing this, and what you will give it.", "ms-MY": "Tetapkan mengapa anda melakukannya, dan apa yang anda akan beri.", "id-ID": "Tetapkan mengapa Anda melakukannya, dan apa yang Anda berikan."}'::jsonb, '{"en": "This challenge builds character, discipline and capability. It does not promise a closing — it builds the behaviour, pipeline and accountability that can create one. Closing is helping: you are not pushing anyone, you are helping someone decide well.", "ms-MY": "Cabaran ini membina sahsiah, disiplin dan keupayaan. Ia tidak menjanjikan closing — ia membina tingkah laku, pipeline dan akauntabiliti yang boleh mencipta satu. Closing itu membantu: anda tidak memaksa sesiapa, anda membantu seseorang membuat keputusan yang baik.", "id-ID": "Tantangan ini membangun karakter, disiplin dan kapabilitas. Ini tidak menjanjikan closing — ini membangun perilaku, pipeline dan akuntabilitas yang bisa menciptakannya. Closing adalah membantu: Anda tidak menekan siapa pun, Anda membantu seseorang mengambil keputusan yang tepat."}'::jsonb,
    null, '{"en": "Write your 30-day goal, your personal reason, and the hours you can genuinely give each day.", "ms-MY": "Tulis matlamat 30 hari, sebab peribadi anda, dan jumlah jam yang benar-benar boleh anda beri setiap hari.", "id-ID": "Tulis target 30 hari, alasan pribadi Anda, dan jam yang benar-benar bisa Anda berikan setiap hari."}'::jsonb, null, '{"en": "Your commitment, goal and daily available time, in your own words.", "ms-MY": "Ikrar, matlamat dan masa harian anda, dengan kata-kata anda sendiri.", "id-ID": "Komitmen, target dan waktu harian Anda, dengan kata-kata Anda sendiri."}'::jsonb,
    '{"en": "What will make you stop, and what will you do when it happens?", "ms-MY": "Apa yang akan buat anda berhenti, dan apa yang anda akan buat bila ia berlaku?", "id-ID": "Apa yang akan membuat Anda berhenti, dan apa yang akan Anda lakukan saat itu terjadi?"}'::jsonb, '{"en": "Verify the goal is specific and the daily time is realistic, not aspirational. A vague reason predicts a vague month.", "ms-MY": "Sahkan matlamat itu spesifik dan masa harian realistik, bukan angan-angan. Sebab yang kabur meramalkan bulan yang kabur.", "id-ID": "Pastikan target spesifik dan waktu harian realistis, bukan angan-angan. Alasan yang kabur memprediksi bulan yang kabur."}'::jsonb, 20, true,
    null, null, null, 'ok', null);

  -- ---------- Day 2 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 2, 1, '{"en": "Professional Identity & Character", "ms-MY": "Identiti Profesional & Sahsiah", "id-ID": "Identitas Profesional & Karakter"}'::jsonb, '{"en": "Know who you are to a customer before you talk to one.", "ms-MY": "Kenal siapa anda pada pelanggan sebelum anda bercakap dengan seorang pun.", "id-ID": "Kenali siapa Anda di mata pelanggan sebelum berbicara dengan siapa pun."}'::jsonb, '{"en": "Trust is the currency of AG. Your profile, how you present yourself and how you keep your word are part of the product. Strengths are worth naming; so is the one behaviour you know needs work.", "ms-MY": "Kepercayaan ialah mata wang AG. Profil anda, cara anda membawa diri dan cara anda menepati janji adalah sebahagian daripada produk. Kekuatan patut dinamakan; begitu juga satu tingkah laku yang anda tahu perlu diperbaiki.", "id-ID": "Kepercayaan adalah mata uang AG. Profil Anda, cara Anda membawa diri dan cara Anda menepati janji adalah bagian dari produk. Kekuatan layak disebutkan; begitu juga satu perilaku yang Anda tahu perlu diperbaiki."}'::jsonb,
    '{"en": "If you have completed Talent Compass or a Diag assessment, reference it. Hero will not change your result — this is your own reading of it.", "ms-MY": "Jika anda telah melengkapkan Talent Compass atau penilaian Diag, rujuk padanya. Hero tidak akan mengubah keputusan anda — ini bacaan anda sendiri terhadapnya.", "id-ID": "Jika Anda sudah menyelesaikan Talent Compass atau asesmen Diag, rujuk hasilnya. Hero tidak akan mengubah hasil Anda — ini pembacaan Anda sendiri."}'::jsonb, '{"en": "Complete your Hero profile, then name one behaviour you will improve this month.", "ms-MY": "Lengkapkan profil Hero anda, kemudian namakan satu tingkah laku yang anda akan perbaiki bulan ini.", "id-ID": "Lengkapi profil Hero Anda, lalu sebutkan satu perilaku yang akan Anda perbaiki bulan ini."}'::jsonb, null, '{"en": "Your completed profile plus the behaviour you chose and why.", "ms-MY": "Profil lengkap anda serta tingkah laku yang anda pilih dan sebabnya.", "id-ID": "Profil lengkap Anda serta perilaku yang Anda pilih dan alasannya."}'::jsonb,
    '{"en": "What would a customer say about you after one conversation?", "ms-MY": "Apa yang pelanggan akan kata tentang anda selepas satu perbualan?", "id-ID": "Apa yang akan dikatakan pelanggan tentang Anda setelah satu percakapan?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);

