  values (v_ver, 3, 1, '{"en": "Hero & Work Setup", "ms-MY": "Hero & Persediaan Kerja", "id-ID": "Hero & Persiapan Kerja"}'::jsonb, '{"en": "Set up the system you will actually work in for 30 days.", "ms-MY": "Sediakan sistem yang anda benar-benar akan guna selama 30 hari.", "id-ID": "Siapkan sistem yang benar-benar akan Anda gunakan selama 30 hari."}'::jsonb, '{"en": "Everything you do this month should leave a record in Hero: a lead, an activity, a next action, an appointment. That record is what proves your work, drives your daily mission and lets your Coach help you early instead of late.", "ms-MY": "Semua yang anda buat bulan ini patut meninggalkan rekod dalam Hero: lead, aktiviti, tindakan seterusnya, temujanji. Rekod itulah yang membuktikan kerja anda, memacu misi harian dan membolehkan Coach membantu awal, bukan lewat.", "id-ID": "Semua yang Anda lakukan bulan ini harus meninggalkan catatan di Hero: lead, aktivitas, tindakan berikutnya, janji temu. Catatan itulah yang membuktikan kerja Anda, menggerakkan misi harian dan memungkinkan Coach membantu lebih awal."}'::jsonb,
    '{"en": "Never share passwords, OTPs or account secrets with anyone — Hero will never ask for them and neither will your Coach.", "ms-MY": "Jangan sesekali kongsi kata laluan, OTP atau rahsia akaun dengan sesiapa — Hero tidak akan meminta dan Coach anda juga tidak.", "id-ID": "Jangan pernah membagikan kata sandi, OTP atau rahasia akun kepada siapa pun — Hero tidak akan meminta dan Coach Anda juga tidak."}'::jsonb, '{"en": "Complete your working setup and log one real interaction end to end so you know the flow.", "ms-MY": "Lengkapkan persediaan kerja anda dan rekod satu interaksi sebenar dari awal ke akhir supaya anda tahu alirannya.", "id-ID": "Selesaikan persiapan kerja Anda dan catat satu interaksi nyata dari awal sampai akhir agar Anda paham alurnya."}'::jsonb, null, '{"en": "Your setup checklist plus the one interaction you logged.", "ms-MY": "Senarai semak persediaan anda serta satu interaksi yang anda rekod.", "id-ID": "Daftar periksa persiapan Anda serta satu interaksi yang Anda catat."}'::jsonb,
    '{"en": "What part of your working system will break first when you get busy?", "ms-MY": "Bahagian mana dalam sistem kerja anda yang akan gagal dahulu bila anda sibuk?", "id-ID": "Bagian mana dari sistem kerja Anda yang akan jebol lebih dulu saat Anda sibuk?"}'::jsonb, '{"en": "Verify the interaction was logged in Hero, not described in prose. Check no credential was shared in the response.", "ms-MY": "Sahkan interaksi itu direkod dalam Hero, bukan diceritakan sahaja. Pastikan tiada maklumat akaun dikongsi dalam jawapan.", "id-ID": "Pastikan interaksi tercatat di Hero, bukan sekadar diceritakan. Pastikan tidak ada kredensial dibagikan dalam jawaban."}'::jsonb, 10, true,
    null, null, null, 'ok', null);
