    null, '{"en": "Choose your focus, write the customer profile that fits it, and complete the approved product learning for it.", "ms-MY": "Pilih fokus anda, tulis profil pelanggan yang sepadan, dan lengkapkan pembelajaran produk yang diluluskan untuknya.", "id-ID": "Pilih fokus Anda, tulis profil pelanggan yang cocok, dan selesaikan pembelajaran produk yang disetujui untuknya."}'::jsonb, null, '{"en": "Your chosen focus, your customer profile, and the learning you completed.", "ms-MY": "Fokus pilihan anda, profil pelanggan anda, dan pembelajaran yang anda selesaikan.", "id-ID": "Fokus pilihan Anda, profil pelanggan Anda, dan pembelajaran yang Anda selesaikan."}'::jsonb,
