  values (v_ver, 5, 1, '{"en": "Build Your First Lead Pipeline", "ms-MY": "Bina Pipeline Lead Pertama", "id-ID": "Bangun Pipeline Lead Pertama"}'::jsonb, '{"en": "Turn names into real records with a next action.", "ms-MY": "Tukar nama menjadi rekod sebenar dengan tindakan seterusnya.", "id-ID": "Ubah nama menjadi catatan nyata dengan tindakan berikutnya."}'::jsonb, '{"en": "A useful lead is a real person you can ethically contact, who could plausibly want what you have. A name in your head is not a lead. A lead with no next action is a lead you have already started losing.", "ms-MY": "Lead yang berguna ialah orang sebenar yang boleh anda hubungi secara beretika, yang munasabah mahukan apa yang anda ada. Nama dalam kepala bukan lead. Lead tanpa tindakan seterusnya ialah lead yang sudah mula anda hilang.", "id-ID": "Lead yang berguna adalah orang nyata yang bisa Anda hubungi secara etis, yang masuk akal menginginkan apa yang Anda punya. Nama di kepala bukan lead. Lead tanpa tindakan berikutnya adalah lead yang sudah mulai Anda kehilangan."}'::jsonb,
    null, '{"en": "Create real leads in Hero and give every active one a next action and a date.", "ms-MY": "Cipta lead sebenar dalam Hero dan beri setiap yang aktif satu tindakan seterusnya dan tarikh.", "id-ID": "Buat lead nyata di Hero dan beri setiap yang aktif satu tindakan berikutnya dan tanggal."}'::jsonb, null, '{"en": "Your actual lead records in Hero — no screenshots needed.", "ms-MY": "Rekod lead sebenar anda dalam Hero — tiada tangkapan skrin diperlukan.", "id-ID": "Catatan lead nyata Anda di Hero — tidak perlu tangkapan layar."}'::jsonb,
    '{"en": "Which lead are you avoiding, and what are you actually afraid of?", "ms-MY": "Lead mana yang anda elak, dan apa sebenarnya yang anda takutkan?", "id-ID": "Lead mana yang Anda hindari, dan apa sebenarnya yang Anda takutkan?"}'::jsonb, '{"en": "Open the warrior''s lead list. Verify the records are real people with contactable details, and check how many carry a next action date.", "ms-MY": "Buka senarai lead warrior. Sahkan rekod itu orang sebenar dengan maklumat yang boleh dihubungi, dan semak berapa banyak yang ada tarikh tindakan.", "id-ID": "Buka daftar lead warrior. Pastikan catatannya orang nyata dengan detail yang bisa dihubungi, dan periksa berapa yang punya tanggal tindakan."}'::jsonb, 15, true,
    null, 'native_record', '{"source": "leads", "min_count": 1}'::jsonb, 'ok', null);

