    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 6, 2, '{"en": "Cold, Warm, Hot", "ms-MY": "Sejuk, Suam, Panas", "id-ID": "Dingin, Hangat, Panas"}'::jsonb, '{"en": "Know which conversations deserve your next hour.", "ms-MY": "Tahu perbualan mana yang layak untuk sejam anda yang seterusnya.", "id-ID": "Tahu percakapan mana yang layak mendapat jam Anda berikutnya."}'::jsonb, '{"en": "Not every lead deserves the same effort today. Classifying honestly — who is actually warm, who is genuinely cold — is how you stop spending your best energy on the wrong person.", "ms-MY": "Bukan setiap lead layak usaha yang sama hari ini. Mengklasifikasi dengan jujur — siapa yang benar-benar suam, siapa yang memang sejuk — itulah cara anda berhenti membazir tenaga terbaik pada orang yang salah.", "id-ID": "Tidak semua lead layak usaha yang sama hari ini. Mengklasifikasi dengan jujur — siapa yang benar-benar hangat, siapa yang memang dingin — itulah cara Anda berhenti membuang energi terbaik pada orang yang salah."}'::jsonb,
    null, '{"en": "Classify every active lead in Hero and set the next action that matches its temperature.", "ms-MY": "Klasifikasikan setiap lead aktif dalam Hero dan tetapkan tindakan seterusnya yang sepadan dengan suhunya.", "id-ID": "Klasifikasikan setiap lead aktif di Hero dan tetapkan tindakan berikutnya yang sesuai suhunya."}'::jsonb, null, '{"en": "Your updated classification in Hero.", "ms-MY": "Klasifikasi anda yang dikemas kini dalam Hero.", "id-ID": "Klasifikasi Anda yang diperbarui di Hero."}'::jsonb,
    '{"en": "Which lead did you classify warmer than it really is, and why?", "ms-MY": "Lead mana yang anda klasifikasi lebih suam daripada realiti, dan mengapa?", "id-ID": "Lead mana yang Anda klasifikasi lebih hangat dari kenyataannya, dan mengapa?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 7 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 7, 2, '{"en": "Prospecting Rhythm", "ms-MY": "Rentak Prospek", "id-ID": "Ritme Prospek"}'::jsonb, '{"en": "Make outreach a rhythm, not a mood.", "ms-MY": "Jadikan menghubungi orang satu rentak, bukan mood.", "id-ID": "Jadikan menjangkau orang sebuah ritme, bukan suasana hati."}'::jsonb, '{"en": "Consistency beats intensity. A warrior who speaks to a few new people every working day will out-build a warrior who does a burst once a week and then goes quiet.", "ms-MY": "Konsisten mengalahkan intensiti. Warrior yang bercakap dengan beberapa orang baharu setiap hari bekerja akan membina lebih daripada warrior yang buat sekali gus seminggu kemudian senyap.", "id-ID": "Konsistensi mengalahkan intensitas. Warrior yang berbicara dengan beberapa orang baru setiap hari kerja akan membangun lebih dari warrior yang meledak sekali seminggu lalu diam."}'::jsonb,
    null, '{"en": "Do real outreach today and log every conversation in Hero as it happens.", "ms-MY": "Lakukan hubungan sebenar hari ini dan rekod setiap perbualan dalam Hero sebaik ia berlaku.", "id-ID": "Lakukan penjangkauan nyata hari ini dan catat setiap percakapan di Hero saat terjadi."}'::jsonb, null, '{"en": "Your logged activities for today.", "ms-MY": "Aktiviti anda yang direkod untuk hari ini.", "id-ID": "Aktivitas Anda yang tercatat untuk hari ini."}'::jsonb,
    '{"en": "What time of day did you actually do it, and can you protect that slot tomorrow?", "ms-MY": "Pukul berapa anda benar-benar melakukannya, dan bolehkah anda lindungi waktu itu esok?", "id-ID": "Jam berapa Anda benar-benar melakukannya, dan bisakah Anda melindungi slot itu besok?"}'::jsonb, null, 10, true,
    null, 'native_record', '{"source": "activities", "min_count": 1, "window_days": 1}'::jsonb, 'ok', null);

  -- ---------- Day 8 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 8, 2, '{"en": "First Message & Hook", "ms-MY": "Mesej Pertama & Pemikat", "id-ID": "Pesan Pertama & Pemikat"}'::jsonb, '{"en": "Open in a way a real person would answer.", "ms-MY": "Buka perbualan dengan cara yang orang sebenar akan balas.", "id-ID": "Buka percakapan dengan cara yang akan dibalas orang sungguhan."}'::jsonb, '{"en": "The opener decides whether there is a conversation at all. It should sound like a person, be relevant to them, and make the next step small. High outreach with no replies is almost always an opener problem, not an effort problem.", "ms-MY": "Ayat pembuka menentukan sama ada wujud perbualan langsung. Ia patut berbunyi seperti manusia, relevan kepada mereka, dan menjadikan langkah seterusnya kecil. Banyak menghubungi tanpa balasan hampir selalu masalah ayat pembuka, bukan masalah usaha.", "id-ID": "Kalimat pembuka menentukan ada atau tidaknya percakapan. Ia harus terdengar manusiawi, relevan bagi mereka, dan membuat langkah berikutnya kecil. Banyak menjangkau tanpa balasan hampir selalu masalah pembuka, bukan masalah usaha."}'::jsonb,
    null, '{"en": "Use an approved opener suited to the person and the channel, and log what you sent and what came back.", "ms-MY": "Guna ayat pembuka yang diluluskan sesuai dengan orang dan salurannya, dan rekod apa yang anda hantar dan apa yang kembali.", "id-ID": "Gunakan pembuka yang disetujui sesuai orang dan salurannya, lalu catat apa yang Anda kirim dan apa balasannya."}'::jsonb, null, '{"en": "Your activity records, plus the opener you used.", "ms-MY": "Rekod aktiviti anda, serta ayat pembuka yang anda guna.", "id-ID": "Catatan aktivitas Anda, serta pembuka yang Anda gunakan."}'::jsonb,
    '{"en": "Which opener got a reply, and what was different about it?", "ms-MY": "Ayat pembuka mana yang dapat balasan, dan apa yang berbeza mengenainya?", "id-ID": "Pembuka mana yang mendapat balasan, dan apa bedanya?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);
  insert into curriculum_days (version_id, day_no, phase, title, objective,
    content, required_action, evidence_requirement, reflection_question,
    xp_amount, needs_review, country_override, content_status, content_note)
  values (v_ver, 8, 2, '{"en": "First Message & Hook", "ms-MY": "Mesej Pertama & Pemikat", "id-ID": "Pesan Pertama & Pemikat"}'::jsonb, '{"en": "Open in a way a real person would answer.", "ms-MY": "Buka perbualan dengan cara yang orang sebenar akan balas.", "id-ID": "Buka percakapan dengan cara yang akan dibalas orang sungguhan."}'::jsonb,
    '{"en": "CONTENT REQUIRED — MY. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.", "ms-MY": "KANDUNGAN DIPERLUKAN — MY. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.", "id-ID": "KONTEN DIPERLUKAN — MY. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply."}'::jsonb, '{"en": "Use an approved opener suited to the person and the channel, and log what you sent and what came back.", "ms-MY": "Guna ayat pembuka yang diluluskan sesuai dengan orang dan salurannya, dan rekod apa yang anda hantar dan apa yang kembali.", "id-ID": "Gunakan pembuka yang disetujui sesuai orang dan salurannya, lalu catat apa yang Anda kirim dan apa balasannya."}'::jsonb, '{"en": "Your activity records, plus the opener you used.", "ms-MY": "Rekod aktiviti anda, serta ayat pembuka yang anda guna.", "id-ID": "Catatan aktivitas Anda, serta pembuka yang Anda gunakan."}'::jsonb, '{"en": "Which opener got a reply, and what was different about it?", "ms-MY": "Ayat pembuka mana yang dapat balasan, dan apa yang berbeza mengenainya?", "id-ID": "Pembuka mana yang mendapat balasan, dan apa bedanya?"}'::jsonb,
    10, true, 'MY', 'content_required', 'Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.');
  insert into curriculum_days (version_id, day_no, phase, title, objective,
    content, required_action, evidence_requirement, reflection_question,
    xp_amount, needs_review, country_override, content_status, content_note)
  values (v_ver, 8, 2, '{"en": "First Message & Hook", "ms-MY": "Mesej Pertama & Pemikat", "id-ID": "Pesan Pertama & Pemikat"}'::jsonb, '{"en": "Open in a way a real person would answer.", "ms-MY": "Buka perbualan dengan cara yang orang sebenar akan balas.", "id-ID": "Buka percakapan dengan cara yang akan dibalas orang sungguhan."}'::jsonb,
    '{"en": "CONTENT REQUIRED — ID. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.", "ms-MY": "KANDUNGAN DIPERLUKAN — ID. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.", "id-ID": "KONTEN DIPERLUKAN — ID. Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply."}'::jsonb, '{"en": "Use an approved opener suited to the person and the channel, and log what you sent and what came back.", "ms-MY": "Guna ayat pembuka yang diluluskan sesuai dengan orang dan salurannya, dan rekod apa yang anda hantar dan apa yang kembali.", "id-ID": "Gunakan pembuka yang disetujui sesuai orang dan salurannya, lalu catat apa yang Anda kirim dan apa balasannya."}'::jsonb, '{"en": "Your activity records, plus the opener you used.", "ms-MY": "Rekod aktiviti anda, serta ayat pembuka yang anda guna.", "id-ID": "Catatan aktivitas Anda, serta pembuka yang Anda gunakan."}'::jsonb, '{"en": "Which opener got a reply, and what was different about it?", "ms-MY": "Ayat pembuka mana yang dapat balasan, dan apa yang berbeza mengenainya?", "id-ID": "Pembuka mana yang mendapat balasan, dan apa bedanya?"}'::jsonb,
    10, true, 'ID', 'content_required', 'Approved openers and messaging norms for this country: language register, channel etiquette, and any platform or advertising rules that apply.');

  -- ---------- Day 9 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 9, 2, '{"en": "Needs Discovery", "ms-MY": "Menggali Keperluan", "id-ID": "Menggali Kebutuhan"}'::jsonb, '{"en": "Find out what they actually need before you recommend anything.", "ms-MY": "Ketahui apa yang mereka benar-benar perlukan sebelum anda mengesyorkan apa-apa.", "id-ID": "Cari tahu apa yang benar-benar mereka butuhkan sebelum Anda merekomendasikan apa pun."}'::jsonb, '{"en": "Most pipeline stalls because nobody asked. Need, timing and constraint are the three things that decide whether this is real. Ask them properly, record the answers, and you will never guess again.", "ms-MY": "Kebanyakan pipeline tersekat kerana tiada siapa bertanya. Keperluan, masa dan kekangan ialah tiga perkara yang menentukan sama ada ini benar. Tanya dengan betul, rekod jawapannya, dan anda tidak perlu meneka lagi.", "id-ID": "Kebanyakan pipeline macet karena tidak ada yang bertanya. Kebutuhan, waktu dan kendala adalah tiga hal yang menentukan apakah ini nyata. Tanyakan dengan benar, catat jawabannya, dan Anda tidak akan menebak lagi."}'::jsonb,
    '{"en": "Collect only what the customer is willing to share and what you genuinely need. Do not record anything sensitive you were not given freely.", "ms-MY": "Kumpul hanya apa yang pelanggan sudi kongsi dan apa yang anda benar-benar perlukan. Jangan rekod apa-apa yang sensitif yang tidak diberi secara rela.", "id-ID": "Kumpulkan hanya yang pelanggan bersedia bagikan dan yang benar-benar Anda butuhkan. Jangan catat hal sensitif yang tidak diberikan secara sukarela."}'::jsonb, '{"en": "Run a real discovery conversation and record the need, the timing and the constraint in the lead.", "ms-MY": "Jalankan perbualan penggalian sebenar dan rekod keperluan, masa dan kekangan dalam lead itu.", "id-ID": "Lakukan percakapan penggalian nyata dan catat kebutuhan, waktu dan kendala di lead tersebut."}'::jsonb, null, '{"en": "The lead record showing what you learned.", "ms-MY": "Rekod lead yang menunjukkan apa yang anda pelajari.", "id-ID": "Catatan lead yang menunjukkan apa yang Anda pelajari."}'::jsonb,
    '{"en": "What did you assume that turned out to be wrong?", "ms-MY": "Apa yang anda andaikan tetapi rupanya salah?", "id-ID": "Apa yang Anda asumsikan tetapi ternyata salah?"}'::jsonb, '{"en": "Verify the need, timing and constraint are recorded on the lead itself — not summarised only in the submission text.", "ms-MY": "Sahkan keperluan, masa dan kekangan direkod pada lead itu sendiri — bukan diringkaskan dalam teks penghantaran sahaja.", "id-ID": "Pastikan kebutuhan, waktu dan kendala tercatat di lead itu sendiri — bukan hanya diringkas di teks pengiriman."}'::jsonb, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 10 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 10, 2, '{"en": "Building Trust", "ms-MY": "Membina Kepercayaan", "id-ID": "Membangun Kepercayaan"}'::jsonb, '{"en": "Be useful before you are needed.", "ms-MY": "Jadi berguna sebelum anda diperlukan.", "id-ID": "Jadilah berguna sebelum Anda dibutuhkan."}'::jsonb, '{"en": "Trust is built by doing what you said you would do, on the day you said it. A follow-up that adds something useful is worth ten that just check in.", "ms-MY": "Kepercayaan dibina dengan melakukan apa yang anda kata anda akan buat, pada hari anda kata. Satu susulan yang menambah sesuatu yang berguna bernilai sepuluh yang sekadar bertanya khabar.", "id-ID": "Kepercayaan dibangun dengan melakukan apa yang Anda katakan, pada hari yang Anda katakan. Satu follow-up yang menambah sesuatu yang berguna setara sepuluh yang sekadar menyapa."}'::jsonb,
    null, '{"en": "Deliver one genuinely useful follow-up to someone who is waiting on you.", "ms-MY": "Sampaikan satu susulan yang benar-benar berguna kepada seseorang yang menunggu anda.", "id-ID": "Berikan satu follow-up yang benar-benar berguna kepada seseorang yang menunggu Anda."}'::jsonb, null, '{"en": "The logged follow-up, plus a short note on what made it useful.", "ms-MY": "Susulan yang direkod, serta nota ringkas apa yang menjadikannya berguna.", "id-ID": "Follow-up yang tercatat, serta catatan singkat apa yang membuatnya berguna."}'::jsonb,
    '{"en": "Did you promise anything you have not yet delivered?", "ms-MY": "Adakah anda janji apa-apa yang belum anda tunaikan?", "id-ID": "Apakah Anda menjanjikan sesuatu yang belum Anda tunaikan?"}'::jsonb, null, 10, true,
    null, 'native_record', '{"source": "activities", "min_count": 1, "window_days": 2}'::jsonb, 'ok', null);

  -- ---------- Day 11 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 11, 2, '{"en": "Follow-Up Discipline", "ms-MY": "Disiplin Susulan", "id-ID": "Disiplin Follow-Up"}'::jsonb, '{"en": "Clear what is due, today.", "ms-MY": "Selesaikan apa yang perlu, hari ini.", "id-ID": "Selesaikan yang jatuh tempo, hari ini."}'::jsonb, '{"en": "An overdue follow-up is a promise you broke quietly. Clearing your due list usually moves the pipeline more than finding new leads does — the work is already half done.", "ms-MY": "Susulan yang tertunggak ialah janji yang anda mungkiri secara senyap. Membersihkan senarai yang perlu selalunya menggerakkan pipeline lebih daripada mencari lead baharu — kerjanya sudah separuh siap.", "id-ID": "Follow-up yang terlambat adalah janji yang Anda ingkari diam-diam. Menyelesaikan daftar yang jatuh tempo biasanya menggerakkan pipeline lebih dari mencari lead baru — pekerjaannya sudah setengah jalan."}'::jsonb,
    null, '{"en": "Clear every follow-up that is due, and set the next action on each one before you close it.", "ms-MY": "Selesaikan setiap susulan yang perlu, dan tetapkan tindakan seterusnya pada setiap satu sebelum anda tutup.", "id-ID": "Selesaikan setiap follow-up yang jatuh tempo, dan tetapkan tindakan berikutnya sebelum Anda tutup."}'::jsonb, null, '{"en": "Your cleared follow-ups in Hero.", "ms-MY": "Susulan anda yang telah diselesaikan dalam Hero.", "id-ID": "Follow-up Anda yang selesai di Hero."}'::jsonb,
    '{"en": "How many were overdue, and what caused the backlog?", "ms-MY": "Berapa banyak yang tertunggak, dan apa punca timbunan itu?", "id-ID": "Berapa yang terlambat, dan apa penyebab tumpukannya?"}'::jsonb, '{"en": "Check the overdue count before and after. Verify each cleared lead now carries a new next action date.", "ms-MY": "Semak jumlah tertunggak sebelum dan selepas. Sahkan setiap lead yang diselesaikan kini ada tarikh tindakan baharu.", "id-ID": "Periksa jumlah terlambat sebelum dan sesudah. Pastikan setiap lead yang selesai kini punya tanggal tindakan baru."}'::jsonb, 10, true,
    null, 'native_record', '{"source": "activities", "min_count": 1, "window_days": 1}'::jsonb, 'ok', null);

  -- ---------- Day 12 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 12, 2, '{"en": "Appointment Setting", "ms-MY": "Menetapkan Temujanji", "id-ID": "Mengatur Janji Temu"}'::jsonb, '{"en": "Turn a good conversation into a real next step.", "ms-MY": "Tukar perbualan yang baik kepada langkah seterusnya yang nyata.", "id-ID": "Ubah percakapan yang baik menjadi langkah berikutnya yang nyata."}'::jsonb, '{"en": "Qualified conversations with no appointment are the single most common place a new warrior stalls. The ask should be specific, easy and dated — a vague “let me know” is not a next step.", "ms-MY": "Perbualan layak tanpa temujanji ialah tempat paling kerap warrior baharu tersekat. Permintaan itu patut spesifik, mudah dan bertarikh — “beritahu saya nanti” bukan langkah seterusnya.", "id-ID": "Percakapan qualified tanpa janji temu adalah titik paling umum warrior baru macet. Permintaannya harus spesifik, mudah dan bertanggal — “kabari saya nanti” bukan langkah berikutnya."}'::jsonb,
    '{"en": "If you genuinely have no live opportunity ready, tell your Coach and run the approved practice instead. Never invent a customer.", "ms-MY": "Jika anda benar-benar tiada peluang hidup yang bersedia, beritahu Coach anda dan jalankan latihan yang diluluskan. Jangan sesekali reka pelanggan.", "id-ID": "Jika Anda benar-benar tidak punya peluang hidup yang siap, beri tahu Coach Anda dan jalankan latihan yang disetujui. Jangan pernah mengarang pelanggan."}'::jsonb, '{"en": "Move a genuinely engaged opportunity to a clear, dated next step and create the appointment in Hero.", "ms-MY": "Gerakkan peluang yang benar-benar melayan kepada langkah seterusnya yang jelas dan bertarikh, dan cipta temujanji dalam Hero.", "id-ID": "Pindahkan peluang yang benar-benar terlibat ke langkah berikutnya yang jelas dan bertanggal, lalu buat janji temu di Hero."}'::jsonb, null, '{"en": "The appointment record in Hero.", "ms-MY": "Rekod temujanji dalam Hero.", "id-ID": "Catatan janji temu di Hero."}'::jsonb,
    '{"en": "What made them say yes — or what made them hesitate?", "ms-MY": "Apa yang buat mereka setuju — atau apa yang buat mereka teragak-agak?", "id-ID": "Apa yang membuat mereka setuju — atau apa yang membuat mereka ragu?"}'::jsonb, '{"en": "Verify the appointment is a real record with a date. If practice was used instead, confirm you agreed to it beforehand.", "ms-MY": "Sahkan temujanji itu rekod sebenar dengan tarikh. Jika latihan diguna, sahkan anda bersetuju terlebih dahulu.", "id-ID": "Pastikan janji temu adalah catatan nyata dengan tanggal. Jika latihan yang dipakai, konfirmasi Anda menyetujuinya lebih dulu."}'::jsonb, 15, true,
    null, 'native_record', '{"source": "appointments", "min_count": 1}'::jsonb, 'ok', null);

  -- ---------- Day 13 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 13, 3, '{"en": "Project & Product Mastery", "ms-MY": "Menguasai Projek & Produk", "id-ID": "Menguasai Proyek & Produk"}'::jsonb, '{"en": "Go deeper on the focus you already chose.", "ms-MY": "Pergi lebih dalam pada fokus yang anda sudah pilih.", "id-ID": "Perdalam fokus yang sudah Anda pilih."}'::jsonb, '{"en": "This is depth, not first exposure. By now you have had real conversations — you know which questions you could not answer well. This day is for closing those gaps on your chosen focus.", "ms-MY": "Ini kedalaman, bukan pendedahan pertama. Sekarang anda sudah ada perbualan sebenar — anda tahu soalan mana yang anda tidak dapat jawab dengan baik. Hari ini untuk menutup jurang itu pada fokus pilihan anda.", "id-ID": "Ini kedalaman, bukan perkenalan awal. Sekarang Anda sudah punya percakapan nyata — Anda tahu pertanyaan mana yang belum bisa Anda jawab baik. Hari ini untuk menutup celah itu pada fokus pilihan Anda."}'::jsonb,
    null, '{"en": "Complete the approved mastery task for your focus and write the three questions you can now answer that you could not last week.", "ms-MY": "Lengkapkan tugasan penguasaan yang diluluskan untuk fokus anda dan tulis tiga soalan yang kini anda boleh jawab tetapi tidak boleh minggu lepas.", "id-ID": "Selesaikan tugas penguasaan yang disetujui untuk fokus Anda dan tulis tiga pertanyaan yang kini bisa Anda jawab tetapi tidak minggu lalu."}'::jsonb, null, '{"en": "Your completed knowledge check or approved summary.", "ms-MY": "Semakan pengetahuan anda yang lengkap atau ringkasan yang diluluskan.", "id-ID": "Pemeriksaan pengetahuan Anda yang selesai atau ringkasan yang disetujui."}'::jsonb,
    '{"en": "What question do you still hope nobody asks you?", "ms-MY": "Soalan apa yang anda masih harap tiada siapa tanya?", "id-ID": "Pertanyaan apa yang masih Anda harap tidak ada yang menanyakan?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);
  insert into curriculum_days (version_id, day_no, phase, title, objective,
    content, required_action, evidence_requirement, reflection_question,
    xp_amount, needs_review, country_override, content_status, content_note)
  values (v_ver, 13, 3, '{"en": "Project & Product Mastery", "ms-MY": "Menguasai Projek & Produk", "id-ID": "Menguasai Proyek & Produk"}'::jsonb, '{"en": "Go deeper on the focus you already chose.", "ms-MY": "Pergi lebih dalam pada fokus yang anda sudah pilih.", "id-ID": "Perdalam fokus yang sudah Anda pilih."}'::jsonb,
    '{"en": "CONTENT REQUIRED — MY. The approved deep-mastery material for this country''s current focus projects or segments.", "ms-MY": "KANDUNGAN DIPERLUKAN — MY. The approved deep-mastery material for this country''s current focus projects or segments.", "id-ID": "KONTEN DIPERLUKAN — MY. The approved deep-mastery material for this country''s current focus projects or segments."}'::jsonb, '{"en": "Complete the approved mastery task for your focus and write the three questions you can now answer that you could not last week.", "ms-MY": "Lengkapkan tugasan penguasaan yang diluluskan untuk fokus anda dan tulis tiga soalan yang kini anda boleh jawab tetapi tidak boleh minggu lepas.", "id-ID": "Selesaikan tugas penguasaan yang disetujui untuk fokus Anda dan tulis tiga pertanyaan yang kini bisa Anda jawab tetapi tidak minggu lalu."}'::jsonb, '{"en": "Your completed knowledge check or approved summary.", "ms-MY": "Semakan pengetahuan anda yang lengkap atau ringkasan yang diluluskan.", "id-ID": "Pemeriksaan pengetahuan Anda yang selesai atau ringkasan yang disetujui."}'::jsonb, '{"en": "What question do you still hope nobody asks you?", "ms-MY": "Soalan apa yang anda masih harap tiada siapa tanya?", "id-ID": "Pertanyaan apa yang masih Anda harap tidak ada yang menanyakan?"}'::jsonb,
    10, true, 'MY', 'content_required', 'The approved deep-mastery material for this country''s current focus projects or segments.');
