  -- ---------- Day 14 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 14, 3, '{"en": "Value Proposition", "ms-MY": "Cadangan Nilai", "id-ID": "Proposisi Nilai"}'::jsonb, '{"en": "Connect what they need to what you actually have.", "ms-MY": "Hubungkan apa yang mereka perlukan dengan apa yang anda benar-benar ada.", "id-ID": "Hubungkan apa yang mereka butuhkan dengan apa yang benar-benar Anda punya."}'::jsonb, '{"en": "A value proposition is not a feature list. It is one sentence that names their situation, what changes for them, and why you are a credible person to help. If it could be said to anyone, it is not one.", "ms-MY": "Cadangan nilai bukan senarai ciri. Ia satu ayat yang menamakan keadaan mereka, apa yang berubah untuk mereka, dan mengapa anda orang yang boleh dipercayai untuk membantu. Jika ia boleh dikatakan kepada sesiapa, ia bukan cadangan nilai.", "id-ID": "Proposisi nilai bukan daftar fitur. Ia satu kalimat yang menyebut situasi mereka, apa yang berubah bagi mereka, dan mengapa Anda kredibel untuk membantu. Jika bisa dikatakan ke siapa saja, itu bukan proposisi nilai."}'::jsonb,
    null, '{"en": "Write the value statement for one specific real opportunity in your pipeline.", "ms-MY": "Tulis pernyataan nilai untuk satu peluang sebenar yang spesifik dalam pipeline anda.", "id-ID": "Tulis pernyataan nilai untuk satu peluang nyata spesifik dalam pipeline Anda."}'::jsonb, null, '{"en": "Your value statement, naming the actual person and their situation.", "ms-MY": "Pernyataan nilai anda, menamakan orang sebenar dan keadaan mereka.", "id-ID": "Pernyataan nilai Anda, menyebut orang nyata dan situasinya."}'::jsonb,
    '{"en": "Would that sentence still be true if they asked you to prove it?", "ms-MY": "Adakah ayat itu masih benar jika mereka minta anda buktikan?", "id-ID": "Apakah kalimat itu tetap benar jika mereka meminta Anda membuktikannya?"}'::jsonb, '{"en": "Verify the statement names a real opportunity and makes no claim the warrior cannot support.", "ms-MY": "Sahkan pernyataan itu menamakan peluang sebenar dan tidak membuat dakwaan yang warrior tidak boleh sokong.", "id-ID": "Pastikan pernyataan menyebut peluang nyata dan tidak membuat klaim yang tak bisa didukung warrior."}'::jsonb, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 15 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 15, 3, '{"en": "Presentation Structure", "ms-MY": "Struktur Persembahan", "id-ID": "Struktur Presentasi"}'::jsonb, '{"en": "Have a shape to follow when you are nervous.", "ms-MY": "Ada bentuk untuk diikuti bila anda gementar.", "id-ID": "Punya kerangka untuk diikuti saat Anda gugup."}'::jsonb, '{"en": "Opening, discovery, recommendation, next action. That order matters: recommending before discovering is the fastest way to lose someone who was ready to listen.", "ms-MY": "Pembukaan, penggalian, syor, tindakan seterusnya. Susunan itu penting: mengesyorkan sebelum menggali ialah cara terpantas kehilangan orang yang sudah sedia mendengar.", "id-ID": "Pembukaan, penggalian, rekomendasi, tindakan berikutnya. Urutannya penting: merekomendasikan sebelum menggali adalah cara tercepat kehilangan orang yang sudah siap mendengar."}'::jsonb,
    null, '{"en": "Write your outline for the next real presentation you will give, following the four steps.", "ms-MY": "Tulis rangka anda untuk persembahan sebenar seterusnya, mengikut empat langkah itu.", "id-ID": "Tulis kerangka Anda untuk presentasi nyata berikutnya, mengikuti empat langkah itu."}'::jsonb, null, '{"en": "Your outline, or your Coach''s observation of your practice run.", "ms-MY": "Rangka anda, atau pemerhatian Coach terhadap latihan anda.", "id-ID": "Kerangka Anda, atau observasi Coach atas latihan Anda."}'::jsonb,
    '{"en": "Which of the four steps do you naturally skip?", "ms-MY": "Antara empat langkah itu, yang mana anda selalu langkau?", "id-ID": "Dari empat langkah itu, mana yang biasanya Anda lewati?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 16 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 16, 3, '{"en": "The Customer Process Here", "ms-MY": "Proses Pelanggan Di Sini", "id-ID": "Proses Pelanggan Di Sini"}'::jsonb, '{"en": "Know the process your customer will actually go through.", "ms-MY": "Ketahui proses yang pelanggan anda benar-benar akan lalui.", "id-ID": "Ketahui proses yang benar-benar akan dilalui pelanggan Anda."}'::jsonb, '{"en": "A customer decides with more confidence when the person in front of them can explain what happens next, in order, without guessing. This day is country-specific by nature — the professional and customer process is not the same in Malaysia and Indonesia.", "ms-MY": "Pelanggan membuat keputusan dengan lebih yakin bila orang di hadapan mereka boleh terangkan apa yang berlaku seterusnya, mengikut turutan, tanpa meneka. Hari ini bersifat khusus negara — proses profesional dan pelanggan tidak sama di Malaysia dan Indonesia.", "id-ID": "Pelanggan memutuskan dengan lebih yakin ketika orang di depannya bisa menjelaskan apa yang terjadi berikutnya, berurutan, tanpa menebak. Hari ini bersifat spesifik negara — proses profesional dan pelanggan tidak sama di Malaysia dan Indonesia."}'::jsonb,
    null, '{"en": "Learn the approved process for your country and be able to walk a customer through it in order.", "ms-MY": "Pelajari proses yang diluluskan untuk negara anda dan mampu bawa pelanggan melaluinya mengikut turutan.", "id-ID": "Pelajari proses yang disetujui untuk negara Anda dan mampu memandu pelanggan melewatinya secara berurutan."}'::jsonb, null, '{"en": "Your walkthrough of the process in your own words.", "ms-MY": "Penerangan anda tentang proses itu dengan kata-kata sendiri.", "id-ID": "Penjelasan Anda tentang proses itu dengan kata-kata sendiri."}'::jsonb,
    '{"en": "Which step would you struggle to explain to a nervous first-time buyer?", "ms-MY": "Langkah mana yang anda akan sukar terangkan kepada pembeli kali pertama yang gementar?", "id-ID": "Langkah mana yang sulit Anda jelaskan ke pembeli pertama kali yang gugup?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);
  insert into curriculum_days (version_id, day_no, phase, title, objective,
    content, required_action, evidence_requirement, reflection_question,
    xp_amount, needs_review, country_override, content_status, content_note)
  values (v_ver, 16, 3, '{"en": "The Customer Process Here", "ms-MY": "Proses Pelanggan Di Sini", "id-ID": "Proses Pelanggan Di Sini"}'::jsonb, '{"en": "Know the process your customer will actually go through.", "ms-MY": "Ketahui proses yang pelanggan anda benar-benar akan lalui.", "id-ID": "Ketahui proses yang benar-benar akan dilalui pelanggan Anda."}'::jsonb,
    '{"en": "CONTENT REQUIRED — MY. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.", "ms-MY": "KANDUNGAN DIPERLUKAN — MY. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.", "id-ID": "KONTEN DIPERLUKAN — MY. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences."}'::jsonb, '{"en": "Learn the approved process for your country and be able to walk a customer through it in order.", "ms-MY": "Pelajari proses yang diluluskan untuk negara anda dan mampu bawa pelanggan melaluinya mengikut turutan.", "id-ID": "Pelajari proses yang disetujui untuk negara Anda dan mampu memandu pelanggan melewatinya secara berurutan."}'::jsonb, '{"en": "Your walkthrough of the process in your own words.", "ms-MY": "Penerangan anda tentang proses itu dengan kata-kata sendiri.", "id-ID": "Penjelasan Anda tentang proses itu dengan kata-kata sendiri."}'::jsonb, '{"en": "Which step would you struggle to explain to a nervous first-time buyer?", "ms-MY": "Langkah mana yang anda akan sukar terangkan kepada pembeli kali pertama yang gementar?", "id-ID": "Langkah mana yang sulit Anda jelaskan ke pembeli pertama kali yang gugup?"}'::jsonb,
    10, true, 'MY', 'content_required', 'The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.');
  insert into curriculum_days (version_id, day_no, phase, title, objective,
    content, required_action, evidence_requirement, reflection_question,
    xp_amount, needs_review, country_override, content_status, content_note)
  values (v_ver, 16, 3, '{"en": "The Customer Process Here", "ms-MY": "Proses Pelanggan Di Sini", "id-ID": "Proses Pelanggan Di Sini"}'::jsonb, '{"en": "Know the process your customer will actually go through.", "ms-MY": "Ketahui proses yang pelanggan anda benar-benar akan lalui.", "id-ID": "Ketahui proses yang benar-benar akan dilalui pelanggan Anda."}'::jsonb,
    '{"en": "CONTENT REQUIRED — ID. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.", "ms-MY": "KANDUNGAN DIPERLUKAN — ID. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.", "id-ID": "KONTEN DIPERLUKAN — ID. The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences."}'::jsonb, '{"en": "Learn the approved process for your country and be able to walk a customer through it in order.", "ms-MY": "Pelajari proses yang diluluskan untuk negara anda dan mampu bawa pelanggan melaluinya mengikut turutan.", "id-ID": "Pelajari proses yang disetujui untuk negara Anda dan mampu memandu pelanggan melewatinya secara berurutan."}'::jsonb, '{"en": "Your walkthrough of the process in your own words.", "ms-MY": "Penerangan anda tentang proses itu dengan kata-kata sendiri.", "id-ID": "Penjelasan Anda tentang proses itu dengan kata-kata sendiri."}'::jsonb, '{"en": "Which step would you struggle to explain to a nervous first-time buyer?", "ms-MY": "Langkah mana yang anda akan sukar terangkan kepada pembeli kali pertama yang gementar?", "id-ID": "Langkah mana yang sulit Anda jelaskan ke pembeli pertama kali yang gugup?"}'::jsonb,
    10, true, 'ID', 'content_required', 'The professional and customer process in this country, in order, end to end: who does what, at which step, and what the customer experiences.');

  -- ---------- Day 17 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 17, 3, '{"en": "Viewing & Presentation Preparation", "ms-MY": "Persediaan Viewing & Persembahan", "id-ID": "Persiapan Viewing & Presentasi"}'::jsonb, '{"en": "Walk in prepared, not hopeful.", "ms-MY": "Masuk dengan bersedia, bukan sekadar berharap.", "id-ID": "Masuk dengan siap, bukan sekadar berharap."}'::jsonb, '{"en": "Preparation is what separates a professional from an enthusiast. Know who is coming, what they said they need, what you will show, what they will likely ask, and what the next step will be.", "ms-MY": "Persediaan itulah yang membezakan profesional daripada peminat. Tahu siapa yang datang, apa yang mereka kata mereka perlukan, apa yang anda akan tunjuk, apa yang mereka mungkin tanya, dan apa langkah seterusnya.", "id-ID": "Persiapan itulah yang membedakan profesional dari penggemar. Tahu siapa yang datang, apa yang mereka butuhkan, apa yang akan Anda tunjukkan, apa yang mungkin ditanyakan, dan apa langkah berikutnya."}'::jsonb,
    null, '{"en": "Prepare your next real viewing or presentation and record the plan on the appointment.", "ms-MY": "Sediakan viewing atau persembahan sebenar anda yang seterusnya dan rekod pelannya pada temujanji.", "id-ID": "Siapkan viewing atau presentasi nyata Anda berikutnya dan catat rencananya di janji temu."}'::jsonb, null, '{"en": "Your preparation notes on the appointment record.", "ms-MY": "Nota persediaan anda pada rekod temujanji.", "id-ID": "Catatan persiapan Anda di catatan janji temu."}'::jsonb,
    '{"en": "What is the one question you hope they do not ask, and what is your honest answer?", "ms-MY": "Apa satu soalan yang anda harap mereka tidak tanya, dan apa jawapan jujur anda?", "id-ID": "Apa satu pertanyaan yang Anda harap tidak ditanyakan, dan apa jawaban jujur Anda?"}'::jsonb, null, 10, true,
    null, 'native_record', '{"source": "appointments", "min_count": 1}'::jsonb, 'ok', null);

  -- ---------- Day 18 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 18, 3, '{"en": "Conduct the Viewing", "ms-MY": "Jalankan Viewing", "id-ID": "Jalankan Viewing"}'::jsonb, '{"en": "Do it, and capture what actually happened.", "ms-MY": "Lakukan, dan tangkap apa yang benar-benar berlaku.", "id-ID": "Lakukan, dan tangkap apa yang benar-benar terjadi."}'::jsonb, '{"en": "The viewing itself is the easy part to remember and the easy part to forget to record. What they reacted to, what they ignored, and what they asked twice — that is the information that decides your next move.", "ms-MY": "Viewing itu sendiri mudah diingat dan mudah terlupa untuk direkod. Apa yang mereka beri reaksi, apa yang mereka abaikan, dan apa yang mereka tanya dua kali — itulah maklumat yang menentukan langkah anda seterusnya.", "id-ID": "Viewing itu sendiri mudah diingat dan mudah terlupa dicatat. Apa yang mereka respons, apa yang mereka abaikan, dan apa yang mereka tanya dua kali — itulah informasi yang menentukan langkah Anda berikutnya."}'::jsonb,
    null, '{"en": "Conduct the viewing or presentation and complete the record with the outcome.", "ms-MY": "Jalankan viewing atau persembahan dan lengkapkan rekod dengan hasilnya.", "id-ID": "Jalankan viewing atau presentasi dan lengkapi catatan dengan hasilnya."}'::jsonb, null, '{"en": "The completed appointment record in Hero.", "ms-MY": "Rekod temujanji yang lengkap dalam Hero.", "id-ID": "Catatan janji temu yang lengkap di Hero."}'::jsonb,
    '{"en": "What surprised you?", "ms-MY": "Apa yang mengejutkan anda?", "id-ID": "Apa yang mengejutkan Anda?"}'::jsonb, null, 15, true,
    null, 'native_record', '{"source": "appointments", "min_count": 1}'::jsonb, 'ok', null);

  -- ---------- Day 19 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 19, 3, '{"en": "Post-Viewing Follow-Up", "ms-MY": "Susulan Selepas Viewing", "id-ID": "Follow-Up Setelah Viewing"}'::jsonb, '{"en": "Never let a viewing end without a next step.", "ms-MY": "Jangan biarkan viewing tamat tanpa langkah seterusnya.", "id-ID": "Jangan biarkan viewing berakhir tanpa langkah berikutnya."}'::jsonb, '{"en": "A completed viewing with no follow-up is the most expensive gap in the pipeline — the effort is spent and the momentum is thrown away. Follow up while they still remember how it felt.", "ms-MY": "Viewing yang selesai tanpa susulan ialah jurang paling mahal dalam pipeline — usaha sudah dibelanjakan dan momentum dibuang. Buat susulan semasa mereka masih ingat perasaannya.", "id-ID": "Viewing yang selesai tanpa follow-up adalah celah termahal dalam pipeline — usahanya sudah habis dan momentumnya dibuang. Follow up selagi mereka masih ingat rasanya."}'::jsonb,
    null, '{"en": "Follow up on every completed viewing and record their questions, objections, next action and updated stage.", "ms-MY": "Buat susulan bagi setiap viewing yang selesai dan rekod soalan, bantahan, tindakan seterusnya dan peringkat yang dikemas kini.", "id-ID": "Follow up setiap viewing yang selesai dan catat pertanyaan, keberatan, tindakan berikutnya dan tahap yang diperbarui."}'::jsonb, null, '{"en": "The follow-up activity and the updated lead.", "ms-MY": "Aktiviti susulan dan lead yang dikemas kini.", "id-ID": "Aktivitas follow-up dan lead yang diperbarui."}'::jsonb,
    '{"en": "What did they say that you were not expecting?", "ms-MY": "Apa yang mereka kata yang anda tidak jangka?", "id-ID": "Apa yang mereka katakan yang tidak Anda duga?"}'::jsonb, '{"en": "Check whether any completed viewing still has no follow-up logged after it. That gap is the point of this day.", "ms-MY": "Semak sama ada ada viewing selesai yang masih tiada susulan direkod selepasnya. Jurang itulah maksud hari ini.", "id-ID": "Periksa apakah ada viewing selesai yang masih belum ada follow-up setelahnya. Celah itulah inti hari ini."}'::jsonb, 10, true,
    null, 'native_record', '{"source": "activities", "min_count": 1, "window_days": 3}'::jsonb, 'ok', null);

  -- ---------- Day 20 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 20, 3, '{"en": "Objection Handling", "ms-MY": "Mengendali Bantahan", "id-ID": "Menangani Keberatan"}'::jsonb, '{"en": "Diagnose the objection before you answer it.", "ms-MY": "Kenal pasti bantahan sebelum anda menjawabnya.", "id-ID": "Diagnosis keberatan sebelum Anda menjawabnya."}'::jsonb, '{"en": "“Too expensive” is rarely about price. Most objections are really about timing, trust, fit or someone else who has to agree. Answering the wrong one politely still loses the sale.", "ms-MY": "“Terlalu mahal” jarang tentang harga. Kebanyakan bantahan sebenarnya tentang masa, kepercayaan, kesesuaian atau orang lain yang perlu bersetuju. Menjawab yang salah dengan sopan tetap kehilangan jualan.", "id-ID": "“Terlalu mahal” jarang soal harga. Kebanyakan keberatan sebenarnya soal waktu, kepercayaan, kecocokan atau orang lain yang harus setuju. Menjawab yang salah dengan sopan tetap kehilangan penjualan."}'::jsonb,
    null, '{"en": "Take a real objection you have received, name its type, and write your response plan.", "ms-MY": "Ambil satu bantahan sebenar yang anda terima, namakan jenisnya, dan tulis pelan jawapan anda.", "id-ID": "Ambil satu keberatan nyata yang Anda terima, sebutkan jenisnya, dan tulis rencana jawaban Anda."}'::jsonb, null, '{"en": "The objection, its type, and your plan.", "ms-MY": "Bantahan itu, jenisnya, dan pelan anda.", "id-ID": "Keberatan itu, jenisnya, dan rencana Anda."}'::jsonb,
    '{"en": "Which objection makes you defensive, and why?", "ms-MY": "Bantahan mana yang buat anda defensif, dan mengapa?", "id-ID": "Keberatan mana yang membuat Anda defensif, dan mengapa?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 21 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 21, 3, '{"en": "Negotiation & Decision Support", "ms-MY": "Rundingan & Sokongan Keputusan", "id-ID": "Negosiasi & Dukungan Keputusan"}'::jsonb, '{"en": "Help someone decide well, without pressure.", "ms-MY": "Bantu seseorang membuat keputusan yang baik, tanpa tekanan.", "id-ID": "Bantu seseorang memutuskan dengan baik, tanpa tekanan."}'::jsonb, '{"en": "Responsible support means being clear about what is fixed, what is possible and what is not yours to promise. Never commit on behalf of anyone who has not agreed, and never state a term you have not been authorised to state.", "ms-MY": "Sokongan yang bertanggungjawab bermaksud jelas tentang apa yang tetap, apa yang mungkin dan apa yang bukan hak anda untuk janjikan. Jangan sesekali berjanji bagi pihak sesiapa yang belum bersetuju, dan jangan nyatakan terma yang anda tidak diberi kuasa untuk nyatakan.", "id-ID": "Dukungan yang bertanggung jawab berarti jelas tentang apa yang tetap, apa yang mungkin dan apa yang bukan hak Anda untuk janjikan. Jangan pernah berkomitmen atas nama siapa pun yang belum setuju, dan jangan menyatakan syarat yang tidak Anda punya wewenang untuk sebutkan."}'::jsonb,
    null, '{"en": "Support one real negotiation and record what was agreed, what is still open, and the next action with a date.", "ms-MY": "Sokong satu rundingan sebenar dan rekod apa yang dipersetujui, apa yang masih terbuka, dan tindakan seterusnya dengan tarikh.", "id-ID": "Dukung satu negosiasi nyata dan catat apa yang disepakati, apa yang masih terbuka, dan tindakan berikutnya dengan tanggal."}'::jsonb, null, '{"en": "The negotiation activity and the updated lead.", "ms-MY": "Aktiviti rundingan dan lead yang dikemas kini.", "id-ID": "Aktivitas negosiasi dan lead yang diperbarui."}'::jsonb,
    '{"en": "Did you feel pressure to promise something? What did you do with it?", "ms-MY": "Adakah anda rasa tertekan untuk janjikan sesuatu? Apa yang anda buat dengannya?", "id-ID": "Apakah Anda merasa tertekan untuk menjanjikan sesuatu? Apa yang Anda lakukan?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);
