  -- ---------- Day 22 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 22, 4, '{"en": "Closing Readiness", "ms-MY": "Kesediaan Closing", "id-ID": "Kesiapan Closing"}'::jsonb, '{"en": "Know exactly what is missing on your strongest opportunity.", "ms-MY": "Tahu dengan tepat apa yang kurang pada peluang terkuat anda.", "id-ID": "Tahu persis apa yang kurang pada peluang terkuat Anda."}'::jsonb, '{"en": "Most closings do not fail — they stall, because nobody wrote down which item is missing, who owns it and by when. An audit turns a vague hope into a list you can work.", "ms-MY": "Kebanyakan closing tidak gagal — ia tergantung, kerana tiada siapa tulis item mana yang kurang, siapa pemiliknya dan bila. Audit menukar harapan kabur kepada senarai yang boleh anda kerjakan.", "id-ID": "Kebanyakan closing tidak gagal — ia macet, karena tidak ada yang menuliskan item mana yang kurang, siapa pemiliknya dan kapan. Audit mengubah harapan kabur menjadi daftar yang bisa Anda kerjakan."}'::jsonb,
    null, '{"en": "Audit your strongest genuine opportunity: what is ready, what is missing, who owns each missing item, by when.", "ms-MY": "Audit peluang tulen terkuat anda: apa yang sedia, apa yang kurang, siapa pemilik setiap item yang kurang, sampai bila.", "id-ID": "Audit peluang tulen terkuat Anda: apa yang siap, apa yang kurang, siapa pemilik tiap item yang kurang, sampai kapan."}'::jsonb, null, '{"en": "Your readiness audit with owners and dates.", "ms-MY": "Audit kesediaan anda dengan pemilik dan tarikh.", "id-ID": "Audit kesiapan Anda dengan pemilik dan tanggal."}'::jsonb,
    '{"en": "What has been missing the longest, and why has nobody chased it?", "ms-MY": "Apa yang paling lama tiada, dan mengapa tiada siapa mengejarnya?", "id-ID": "Apa yang paling lama hilang, dan mengapa tidak ada yang mengejarnya?"}'::jsonb, '{"en": "Verify every missing item has a named owner and a date. An audit without owners is a wish list.", "ms-MY": "Sahkan setiap item yang kurang ada pemilik bernama dan tarikh. Audit tanpa pemilik ialah senarai hajat.", "id-ID": "Pastikan setiap item yang kurang punya pemilik bernama dan tanggal. Audit tanpa pemilik adalah daftar harapan."}'::jsonb, 10, true,
    null, null, null, 'ok', null);
  insert into curriculum_days (version_id, day_no, phase, title, objective,
