  -- ---------- Day 23 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 23, 4, '{"en": "Closing Is Helping", "ms-MY": "Closing Itu Membantu", "id-ID": "Closing Adalah Membantu"}'::jsonb, '{"en": "Check that this is genuinely right for them.", "ms-MY": "Semak bahawa ini benar-benar sesuai untuk mereka.", "id-ID": "Periksa bahwa ini benar-benar tepat untuk mereka."}'::jsonb, '{"en": "If it is not right for them, saying so is the closing. Trust is the currency of AG, and it is spent permanently the first time someone feels pushed into something that did not suit them.", "ms-MY": "Jika ia tidak sesuai untuk mereka, mengatakannya itulah closing. Kepercayaan ialah mata wang AG, dan ia habis selamanya pada kali pertama seseorang rasa dipaksa ke dalam sesuatu yang tidak sesuai.", "id-ID": "Jika tidak tepat untuk mereka, mengatakannya itulah closing. Kepercayaan adalah mata uang AG, dan habis selamanya saat pertama kali seseorang merasa didorong ke sesuatu yang tidak cocok."}'::jsonb,
    null, '{"en": "Review your strongest opportunity purely from the customer''s side and write the honest value statement.", "ms-MY": "Semak peluang terkuat anda semata-mata dari sudut pelanggan dan tulis pernyataan nilai yang jujur.", "id-ID": "Tinjau peluang terkuat Anda murni dari sisi pelanggan dan tulis pernyataan nilai yang jujur."}'::jsonb, null, '{"en": "Your customer-value statement and reflection.", "ms-MY": "Pernyataan nilai pelanggan dan refleksi anda.", "id-ID": "Pernyataan nilai pelanggan dan refleksi Anda."}'::jsonb,
    '{"en": "If they were your family, would you still recommend this?", "ms-MY": "Jika mereka keluarga anda, adakah anda masih akan mengesyorkannya?", "id-ID": "Jika mereka keluarga Anda, apakah Anda tetap merekomendasikannya?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 24 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 24, 4, '{"en": "Documentation & Approved Process", "ms-MY": "Dokumentasi & Proses Diluluskan", "id-ID": "Dokumentasi & Proses Disetujui"}'::jsonb, '{"en": "Get the paperwork right, in the right order.", "ms-MY": "Betulkan dokumen, mengikut turutan yang betul.", "id-ID": "Selesaikan dokumen dengan benar, dalam urutan yang tepat."}'::jsonb, '{"en": "Documentation is where goodwill turns into a completed transaction — or where it quietly dies. Follow the approved process for your country exactly; never improvise a document or a step.", "ms-MY": "Dokumentasi ialah tempat niat baik bertukar menjadi transaksi yang selesai — atau tempat ia mati senyap. Ikut proses yang diluluskan untuk negara anda dengan tepat; jangan sesekali reka dokumen atau langkah.", "id-ID": "Dokumentasi adalah tempat itikad baik berubah menjadi transaksi selesai — atau tempat ia mati diam-diam. Ikuti proses yang disetujui untuk negara Anda dengan tepat; jangan pernah mengarang dokumen atau langkah."}'::jsonb,
    null, '{"en": "Work through the approved documentation checklist for your country on a real or approved practice case.", "ms-MY": "Kerjakan senarai semak dokumentasi yang diluluskan untuk negara anda pada kes sebenar atau latihan yang diluluskan.", "id-ID": "Kerjakan daftar periksa dokumentasi yang disetujui untuk negara Anda pada kasus nyata atau latihan yang disetujui."}'::jsonb, null, '{"en": "Your completed checklist and the current status in Hero.", "ms-MY": "Senarai semak lengkap anda dan status semasa dalam Hero.", "id-ID": "Daftar periksa lengkap Anda dan status terkini di Hero."}'::jsonb,
    '{"en": "Which document do you least understand the purpose of?", "ms-MY": "Dokumen mana yang anda paling kurang faham tujuannya?", "id-ID": "Dokumen mana yang paling tidak Anda pahami tujuannya?"}'::jsonb, null, 10, true,
    null, null, null, 'ok', null);
