  values (v_ver, 24, 4, '{"en": "Documentation & Approved Process", "ms-MY": "Dokumentasi & Proses Diluluskan", "id-ID": "Dokumentasi & Proses Disetujui"}'::jsonb, '{"en": "Get the paperwork right, in the right order.", "ms-MY": "Betulkan dokumen, mengikut turutan yang betul.", "id-ID": "Selesaikan dokumen dengan benar, dalam urutan yang tepat."}'::jsonb,
