  -- ---------- Day 25 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 25, 4, '{"en": "Pipeline Rescue", "ms-MY": "Penyelamatan Pipeline", "id-ID": "Penyelamatan Pipeline"}'::jsonb, '{"en": "Deal with everything that went quiet.", "ms-MY": "Uruskan semua yang telah menjadi sepi.", "id-ID": "Tangani semua yang menjadi sepi."}'::jsonb, '{"en": "Every pipeline accumulates silence. Hero will show you exactly where: overdue follow-ups, leads with no next action, stagnant leads, viewings with no follow-up, qualified people with no appointment. You decide what each one deserves.", "ms-MY": "Setiap pipeline mengumpul kesenyapan. Hero akan tunjuk anda tepat di mana: susulan tertunggak, lead tanpa tindakan seterusnya, lead yang beku, viewing tanpa susulan, orang layak tanpa temujanji. Anda tentukan apa yang setiap satu layak dapat.", "id-ID": "Setiap pipeline mengumpulkan keheningan. Hero akan menunjukkan persis di mana: follow-up terlambat, lead tanpa tindakan berikutnya, lead yang mandek, viewing tanpa follow-up, orang qualified tanpa janji temu. Anda putuskan apa yang layak untuk masing-masing."}'::jsonb,
    '{"en": "Hero may suggest what looks stuck. The decision about a real customer is always yours.", "ms-MY": "Hero mungkin cadangkan apa yang kelihatan tersekat. Keputusan tentang pelanggan sebenar sentiasa milik anda.", "id-ID": "Hero mungkin menyarankan apa yang tampak macet. Keputusan tentang pelanggan nyata selalu milik Anda."}'::jsonb, '{"en": "Work through every flagged lead and decide: follow up, nurture, requalify, or disqualify responsibly.", "ms-MY": "Kerjakan setiap lead yang ditanda dan putuskan: susul, pelihara, layak semula, atau lepaskan secara bertanggungjawab.", "id-ID": "Kerjakan setiap lead yang ditandai dan putuskan: follow up, pelihara, kualifikasi ulang, atau lepaskan secara bertanggung jawab."}'::jsonb, null, '{"en": "Your decisions recorded on each lead.", "ms-MY": "Keputusan anda direkod pada setiap lead.", "id-ID": "Keputusan Anda tercatat di setiap lead."}'::jsonb,
    '{"en": "Which lead did you hold on to for your sake rather than theirs?", "ms-MY": "Lead mana yang anda pegang untuk kepentingan anda dan bukan mereka?", "id-ID": "Lead mana yang Anda pertahankan demi Anda, bukan demi mereka?"}'::jsonb, null, 10, true,
    null, 'native_record', '{"source": "activities", "min_count": 1, "window_days": 1}'::jsonb, 'ok', null);

