  values (v_ver, 26, 4, '{"en": "Personal Closing Plan", "ms-MY": "Pelan Closing Peribadi", "id-ID": "Rencana Closing Pribadi"}'::jsonb, '{"en": "Turn your best opportunities into a dated plan.", "ms-MY": "Tukar peluang terbaik anda kepada pelan bertarikh.", "id-ID": "Ubah peluang terbaik Anda menjadi rencana bertanggal."}'::jsonb, '{"en": "A plan is not a list of hopes. Each line names the opportunity, the action, who owns it, what it depends on, and when it is due. Anything without a date is not in the plan.", "ms-MY": "Pelan bukan senarai harapan. Setiap baris menamakan peluang, tindakan, siapa pemiliknya, apa yang ia bergantung padanya, dan bila tarikh akhirnya. Apa-apa tanpa tarikh bukan sebahagian pelan.", "id-ID": "Rencana bukan daftar harapan. Setiap baris menyebut peluang, tindakan, siapa pemiliknya, apa ketergantungannya, dan kapan tenggatnya. Apa pun tanpa tanggal bukan bagian rencana."}'::jsonb,
    null, '{"en": "Write your closing plan for your strongest real opportunities and share it with your Coach.", "ms-MY": "Tulis pelan closing anda untuk peluang sebenar terkuat dan kongsi dengan Coach anda.", "id-ID": "Tulis rencana closing Anda untuk peluang nyata terkuat dan bagikan ke Coach Anda."}'::jsonb, null, '{"en": "Your plan: opportunity, action, owner, dependency, due date.", "ms-MY": "Pelan anda: peluang, tindakan, pemilik, kebergantungan, tarikh akhir.", "id-ID": "Rencana Anda: peluang, tindakan, pemilik, ketergantungan, tenggat."}'::jsonb,
    '{"en": "Which line are you least confident about, and what would make it solid?", "ms-MY": "Baris mana yang anda paling kurang yakin, dan apa yang akan menjadikannya kukuh?", "id-ID": "Baris mana yang paling tidak Anda yakini, dan apa yang membuatnya kokoh?"}'::jsonb, '{"en": "Verify every line has an owner and a date, and that the opportunities named exist in the pipeline.", "ms-MY": "Sahkan setiap baris ada pemilik dan tarikh, dan peluang yang dinamakan wujud dalam pipeline.", "id-ID": "Pastikan setiap baris punya pemilik dan tanggal, dan peluang yang disebut ada di pipeline."}'::jsonb, 15, true,
    null, null, null, 'ok', null);

  -- ---------- Day 27 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 27, 4, '{"en": "Structured Coach Review", "ms-MY": "Semakan Coach Berstruktur", "id-ID": "Tinjauan Coach Terstruktur"}'::jsonb, '{"en": "Sit down with your Coach and look at the real picture.", "ms-MY": "Duduk dengan Coach anda dan lihat gambaran sebenar.", "id-ID": "Duduk bersama Coach Anda dan lihat gambaran nyatanya."}'::jsonb, '{"en": "Hero generates the summary before you meet: your activity, your consistency, your funnel, your current bottleneck. That means the conversation can be about what to do, not about what happened.", "ms-MY": "Hero menjana ringkasan sebelum anda berjumpa: aktiviti anda, konsistensi anda, funnel anda, halangan semasa anda. Maknanya perbualan boleh tentang apa yang perlu dibuat, bukan tentang apa yang telah berlaku.", "id-ID": "Hero membuat ringkasan sebelum Anda bertemu: aktivitas Anda, konsistensi Anda, funnel Anda, hambatan Anda saat ini. Artinya percakapan bisa fokus pada apa yang harus dilakukan, bukan apa yang sudah terjadi."}'::jsonb,
    null, '{"en": "Attend your structured review and record the agreed next actions with dates.", "ms-MY": "Hadiri semakan berstruktur anda dan rekod tindakan seterusnya yang dipersetujui dengan tarikh.", "id-ID": "Hadiri tinjauan terstruktur Anda dan catat tindakan berikutnya yang disepakati dengan tanggal."}'::jsonb, null, '{"en": "The coaching report and your acknowledgement of it.", "ms-MY": "Laporan coaching dan pengakuan anda terhadapnya.", "id-ID": "Laporan coaching dan pengakuan Anda atasnya."}'::jsonb,
    '{"en": "What did your Coach see that you had not?", "ms-MY": "Apa yang Coach anda nampak yang anda tidak nampak?", "id-ID": "Apa yang Coach Anda lihat yang tidak Anda lihat?"}'::jsonb, null, 20, true,
    null, null, null, 'ok', null);

  -- ---------- Day 28 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 28, 4, '{"en": "Contribution & Responsible Recruitment", "ms-MY": "Sumbangan & Rekrut Bertanggungjawab", "id-ID": "Kontribusi & Rekrutmen Bertanggung Jawab"}'::jsonb, '{"en": "Give back — but only after your own customers are handled.", "ms-MY": "Beri kembali — tetapi hanya selepas pelanggan anda sendiri diuruskan.", "id-ID": "Beri kembali — tetapi hanya setelah pelanggan Anda sendiri tertangani."}'::jsonb, '{"en": "If your pipeline is strong, teaching someone else is how the group compounds. If your pipeline is still thin, recovering it IS your contribution this month — nobody is served by recruiting on top of unfinished customer work.", "ms-MY": "Jika pipeline anda kukuh, mengajar orang lain ialah cara kumpulan berkembang. Jika pipeline anda masih nipis, memulihkannya ITULAH sumbangan anda bulan ini — tiada siapa mendapat manfaat daripada merekrut di atas kerja pelanggan yang belum selesai.", "id-ID": "Jika pipeline Anda kuat, mengajari orang lain adalah cara grup bertumbuh. Jika pipeline Anda masih tipis, memulihkannya ITULAH kontribusi Anda bulan ini — tidak ada yang diuntungkan dari merekrut di atas pekerjaan pelanggan yang belum selesai."}'::jsonb,
    null, '{"en": "If your pipeline is healthy: teach, refer or responsibly introduce someone. If it is not: run pipeline recovery instead, and say so.", "ms-MY": "Jika pipeline anda sihat: ajar, rujuk atau perkenalkan seseorang secara bertanggungjawab. Jika tidak: jalankan pemulihan pipeline, dan nyatakannya.", "id-ID": "Jika pipeline Anda sehat: ajari, rujuk atau perkenalkan seseorang secara bertanggung jawab. Jika tidak: jalankan pemulihan pipeline, dan katakan itu."}'::jsonb, null, '{"en": "Whichever track you took, and why you chose it.", "ms-MY": "Trek mana pun yang anda ambil, dan mengapa anda memilihnya.", "id-ID": "Jalur mana pun yang Anda ambil, dan mengapa Anda memilihnya."}'::jsonb,
    '{"en": "Was that choice honest about where your pipeline actually is?", "ms-MY": "Adakah pilihan itu jujur tentang di mana pipeline anda sebenarnya berada?", "id-ID": "Apakah pilihan itu jujur tentang posisi pipeline Anda sebenarnya?"}'::jsonb, '{"en": "Check the warrior chose the track their pipeline actually justifies. Recruitment should not be replacing unfinished customer work.", "ms-MY": "Semak warrior memilih trek yang pipeline mereka benar-benar wajarkan. Rekrut tidak patut menggantikan kerja pelanggan yang belum selesai.", "id-ID": "Periksa warrior memilih jalur yang memang dibenarkan pipeline-nya. Rekrutmen tidak boleh menggantikan pekerjaan pelanggan yang belum selesai."}'::jsonb, 10, true,
    null, null, null, 'ok', null);

  -- ---------- Day 29 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 29, 4, '{"en": "My Hero Playbook", "ms-MY": "Playbook Hero Saya", "id-ID": "Playbook Hero Saya"}'::jsonb, '{"en": "Write down what worked, so next month is not luck.", "ms-MY": "Tulis apa yang berkesan, supaya bulan depan bukan nasib.", "id-ID": "Tulis apa yang berhasil, agar bulan depan bukan keberuntungan."}'::jsonb, '{"en": "Thirty days of your own data tells you when you actually work, how you actually prospect, which message actually gets replies. That is your playbook — not a template someone gave you.", "ms-MY": "Tiga puluh hari data anda sendiri memberitahu bila anda benar-benar bekerja, bagaimana anda benar-benar mencari prospek, mesej mana yang benar-benar dapat balasan. Itulah playbook anda — bukan templat yang orang beri.", "id-ID": "Tiga puluh hari data Anda sendiri memberi tahu kapan Anda benar-benar bekerja, bagaimana Anda benar-benar mencari prospek, pesan mana yang benar-benar dibalas. Itulah playbook Anda — bukan template pemberian orang."}'::jsonb,
    null, '{"en": "Review the patterns Hero observed in your own 30 days, correct them where they are wrong, and approve your playbook.", "ms-MY": "Semak corak yang Hero perhatikan dalam 30 hari anda sendiri, betulkan di mana ia salah, dan luluskan playbook anda.", "id-ID": "Tinjau pola yang Hero amati dalam 30 hari Anda sendiri, perbaiki yang salah, dan setujui playbook Anda."}'::jsonb, null, '{"en": "Your approved playbook: rhythm, prospecting, follow-up, approach, messages, review habit.", "ms-MY": "Playbook anda yang diluluskan: rentak, prospek, susulan, pendekatan, mesej, tabiat semakan.", "id-ID": "Playbook Anda yang disetujui: ritme, prospek, follow-up, pendekatan, pesan, kebiasaan tinjauan."}'::jsonb,
    '{"en": "What will you keep doing, and what will you stop?", "ms-MY": "Apa yang anda akan teruskan, dan apa yang anda akan berhentikan?", "id-ID": "Apa yang akan Anda lanjutkan, dan apa yang akan Anda hentikan?"}'::jsonb, null, 15, true,
    null, null, null, 'ok', null);

  -- ---------- Day 30 ----------
  insert into curriculum_days (version_id, day_no, phase, title, objective, content,
    instructions, required_action, stretch_action, evidence_requirement,
    reflection_question, coach_guidance, xp_amount, needs_review,
    country_override, proof_type, proof_config, content_status, content_note)
  values (v_ver, 30, 4, '{"en": "Final Review & Next Journey", "ms-MY": "Semakan Akhir & Perjalanan Seterusnya", "id-ID": "Tinjauan Akhir & Perjalanan Berikutnya"}'::jsonb, '{"en": "Look at everything you actually built.", "ms-MY": "Lihat semua yang anda benar-benar bina.", "id-ID": "Lihat semua yang benar-benar Anda bangun."}'::jsonb, '{"en": "Reaching Day 30 is not graduation. Programme completion, activity achievement, capability development, pipeline progress and a verified closing are five separate things — and you can finish this programme strong without a closing yet. Your Coach reviews all of it, and graduation stays a human decision.", "ms-MY": "Sampai Hari 30 bukan graduasi. Penyempurnaan program, pencapaian aktiviti, pembangunan keupayaan, kemajuan pipeline dan closing yang disahkan ialah lima perkara berasingan — dan anda boleh tamatkan program ini dengan kuat tanpa closing lagi. Coach anda menyemak semuanya, dan graduasi kekal keputusan manusia.", "id-ID": "Mencapai Hari 30 bukan kelulusan. Penyelesaian program, pencapaian aktivitas, pengembangan kapabilitas, kemajuan pipeline dan closing terverifikasi adalah lima hal terpisah — dan Anda bisa menyelesaikan program ini dengan kuat tanpa closing. Coach Anda meninjau semuanya, dan kelulusan tetap keputusan manusia."}'::jsonb,
    null, '{"en": "Complete your final review with your Coach and agree your next-stage development.", "ms-MY": "Lengkapkan semakan akhir dengan Coach anda dan persetujui pembangunan peringkat seterusnya.", "id-ID": "Selesaikan tinjauan akhir dengan Coach Anda dan sepakati pengembangan tahap berikutnya."}'::jsonb, null, '{"en": "Your final review record and the agreed next stage.", "ms-MY": "Rekod semakan akhir anda dan peringkat seterusnya yang dipersetujui.", "id-ID": "Catatan tinjauan akhir Anda dan tahap berikutnya yang disepakati."}'::jsonb,
    '{"en": "Who are you as a professional now that you were not 30 days ago?", "ms-MY": "Siapa anda sebagai profesional sekarang yang anda bukan 30 hari lalu?", "id-ID": "Siapa Anda sebagai profesional sekarang yang bukan Anda 30 hari lalu?"}'::jsonb, '{"en": "Review completion, activity, capability, pipeline and any verified closing separately. Day 30 raises the review; it never graduates anyone.", "ms-MY": "Semak penyempurnaan, aktiviti, keupayaan, pipeline dan sebarang closing yang disahkan secara berasingan. Hari 30 membangkitkan semakan; ia tidak pernah menggraduasikan sesiapa.", "id-ID": "Tinjau penyelesaian, aktivitas, kapabilitas, pipeline dan closing terverifikasi secara terpisah. Hari 30 memunculkan tinjauan; ia tidak pernah meluluskan siapa pun."}'::jsonb, 30, true,
    null, null, null, 'ok', null);

  perform audit_log('curriculum_version_created','curriculum_version', v_ver::text, null,
